# Surah Yunus (chapter 10) — part 4: ayat 31-40 (IDs 1395-1404)
SURAH = 10

ENTRIES = {
1395: (
"کہدو — کون — تمہیں — آسمان اور زمین سے — رزق دیتا ہے — یا — کون — کان اور آنکھوں کا — مالک ہے — اور — کون — زندگی — کو موت سے — نکالتا ہے — اور موت — کو زندگی سے — نکالتا ہے — اور — کون — معاملات — کی تدبیر کرتا ہے — پس — وہ — کہیں گے — اللہ — پس کہدو — کیا — تم — ڈرتے نہیں",
"""۱۔ رزق — آسمان اور زمین کا — کن — کی ملکیت — جوالہ — اللہ کی۔
۲۔ ’’قُلْ مَن يَرْزُقُكُم مِّنَ السَّمَاءِ وَالْأَرْضِ أَمَّن يَمْلِكُ السَّمْعَ وَالْأَبْصَارَ وَمَن يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَمَن يُدَبِّرُ الْأَمْرَ فَسَيَقُولُونَ اللَّهُ فَقُلْ أَفَلَا تَتَّقُونَ‘‘ — کہدو — کون — تمہیں — آسمان اور زمین سے — رزق دیتا ہے — یا — کون — کان اور آنکھوں کا — مالک ہے — اور — کون — زندگی — کو موت سے — نکالتا ہے — اور موت — کو زندگی سے — نکالتا ہے — اور — کون — معاملات — کی تدبیر کرتا ہے — پس — وہ — کہیں گے — اللہ — پس کہدو — کیا — تم — ڈرتے نہیں — یعنی سب کچھ کرنے والا — اللہ — ہے؛ پھر کیوں شرک کرتے ہو — اور نہیں ڈرتے۔
۳۔ عملی سبق: اللہ — ہر نعمت کا مالک ہے؛ اس سے ڈرتے رہو۔"""
),
1396: (
"پس — یہی — اللہ — تمہارا — حقیقی رب ہے — پس — حق کے بعد — بجز گمراہی کے — کیا — ہے — پس — کہاں — سے — تم — پھیرے جاتے ہو",
"""۱۔ اللہ — حقیقی رب — حق کے بعد — صرف ضلالت — ہے۔
۲۔ ’’فَذَٰلِكُمُ اللَّهُ رَبُّكُمُ الْحَقُّ فَمَاذَا بَعْدَ الْحَقِّ إِلَّا الضَّلَالُ فَأَنَّىٰ تُصْرَفُونَ‘‘ — پس — یہی — اللہ — تمہارا — حقیقی رب ہے — پس — حق کے بعد — بجز گمراہی کے — کیا — ہے — پس — کہاں — سے — تم — پھیرے جاتے ہو — یعنی حق — کے بعد صرف — گمراہی ہے؛ تم کہاں — سے — پھیرے جاتے ہو۔
۳۔ عملی سبق: حق — پہچان لو؛ حق کے بعد — صرف گمراہی ہے۔"""
),
1397: (
"اسی طرح — تمہارے رب — کا — حکم — فاسقوں — پر ثابت ہو گیا — کہ — وہ — ایمان نہ لائیں گے",
"""۱۔ فاسق — اللہ کے حکم کے مطابق — ایمان — نہیں لاتے۔
۲۔ ’’كَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى الَّذِينَ فَسَقُوا أَنَّهُمْ لَا يُؤْمِنُونَ‘‘ — اسی طرح — تمہارے رب — کا — حکم — فاسقوں — پر ثابت ہو گیا — کہ — وہ — ایمان نہ لائیں گے — یعنی اللہ کا حکم — فاسقوں پر — ثابت ہو گیا کہ وہ ایمان — نہیں لائیں گے۔
۳۔ عملی سبق: فسق — ایمان سے محرومی — کا سبب ہے۔"""
),
1398: (
"کہدو — کیا — تمہارے شریکوں میں — کوئی — ہے — جو — خلقت — کا — آغاز کرے — پھر — اسے — دوبارہ پیدا کرے — کہدو — اللہ — خلقت کا آغاز کرتا ہے — پھر — اسے دوبارہ پیدا کرتا ہے — پس — کہاں — سے — تم — پھرائے جاتے ہو",
"""۱۔ دوبار پیدا کرنے کا — اختیار — صرف اللہ کا۔
۲۔ ’’قُلْ هَلْ مِن شُرَكَائِكُم مَّن يَبْدَأُ الْخَلْقَ ثُمَّ يُعِيدُهُ قُلِ اللَّهُ يَبْدَأُ الْخَلْقَ ثُمَّ يُعِيدُهُ فَأَنَّىٰ تُؤْفَكُونَ‘‘ — کہدو — کیا — تمہارے شریکوں میں — کوئی — ہے — جو — خلقت — کا — آغاز کرے — پھر — اسے — دوبارہ پیدا کرے — کہدو — اللہ — خلقت کا آغاز کرتا ہے — پھر — اسے دوبارہ پیدا کرتا ہے — پس — کہاں — سے — تم — پھرائے جاتے ہو — یعنی تمہارے شرکاء — نہ — خلقت کا آغاز کر سکتے ہیں — نہ دوبارہ — پیدا کر سکتے ہیں؛ صرف اللہ — کر سکتا ہے۔
۳۔ عملی سبق: پیدا اور دوبارہ — پوری قدرت — صرف اللہ کی۔"""
),
1399: (
"کہدو — کیا — تمہارے شریکوں میں — کوئی — ہے — جو — حق کی طرف — ہدایت دے — کہدو — اللہ — حق کی طرف — ہدایت دیتا ہے — پس — کیا — جو حق کی طرف — ہدایت دیتا ہے — وہ — پیروی کے زیادہ لائق ہے — یا — وہ — جو — ہدایت — یافتہ نہیں — مگر — جب — اسے ہدایت دی جائے — پس — تمہیں — کیا — ہو گیا — تم — کیسے فیصلہ کرتے ہو",
"""۱۔ ہدایت — صرف — اللہ کے پاس ہے۔
۲۔ ’’قُلْ هَلْ مِن شُرَكَائِكُم مَّن يَهْدِي إِلَى الْحَقِّ قُلِ اللَّهُ يَهْدِي لِلْحَقِّ أَفَمَن يَهْدِي إِلَى الْحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّي إِلَّا أَن يُهْدَىٰ فَمَا لَكُمْ كَيْفَ تَحْكُمُونَ‘‘ — کہدو — کیا — تمہارے شریکوں میں — کوئی — ہے — جو — حق کی طرف — ہدایت دے — کہدو — اللہ — حق کی طرف — ہدایت دیتا ہے — پس — کیا — جو حق کی طرف — ہدایت دیتا ہے — وہ — پیروی کے زیادہ لائق ہے — یا — وہ — جو — ہدایت — یافتہ نہیں — مگر — جب — اسے ہدایت دی جائے — پس — تمہیں — کیا — ہو گیا — تم — کیسے فیصلہ کرتے ہو — یعنی تمہارے شرکاء — نہ — ہدایت دے سکتے ہیں — نہ خود — ہدایت یافتہ ہیں — صرف اللہ — ہدایت دیتا ہے۔
۳۔ عملی سبق: ہدایت — صرف — اللہ کی طرف سے — اور رسولؐ — کی پیروی میں۔"""
),
1400: (
"اور — ان — میں سے — اکثر — صرف گمان — کی پیروی کرتے ہیں — بے شک — گمان — حق سے کچھ — فائدہ نہیں دیتا — بے شک — اللہ — ان — کے — اعمال — سے — باخبر ہے",
"""۱۔ گمان — حق کی جگہ نہیں لے سکتا۔
۲۔ ’’وَمَا يَتَّبِعُ أَكْثَرُهُمْ إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا إِنَّ اللَّهَ عَلِيمٌ بِمَا يَفْعَلُونَ‘‘ — اور — ان — میں سے — اکثر — صرف گمان — کی پیروی کرتے ہیں — بے شک — گمان — حق سے کچھ — فائدہ نہیں دیتا — بے شک — اللہ — ان — کے — اعمال — سے — باخبر ہے — یعنی گمان — حق — کی جگہ نہیں لے سکتا؛ اللہ — ان کے اعمال باخبر ہے۔
۳۔ عملی سبق: یقین — پر عمل کریں؛ گمان — ناکافی ہے۔"""
),
1401: (
"اور — یہ — قرآن — نہیں — کہ — اللہ کے سوا — کسی اور نے — گھڑا — بلکہ — اس — کی تصدیق — اس — چیز — کی جو اس کے — آگے ہے — اور — کتاب — کی تفصیل — ہے — اس میں — کوئی شک نہیں — رب العالمین کی طرف سے",
"""۱۔ قرآن — اللہ کی کتاب ہے — شک سے پاک — پچھلی کتب کی تصدیق۔
۲۔ ’’وَمَا كَانَ هَٰذَا الْقُرْآنُ أَن يُفْتَرَىٰ مِن دُونِ اللَّهِ وَلَٰكِن تَصْدِيقَ الَّذِي بَيْنَ يَدَيْهِ وَتَفْصِيلَ الْكِتَابِ لَا رَيْبَ فِيهِ مِن رَّبِّ الْعَالَمِينَ‘‘ — اور — یہ — قرآن — نہیں — کہ — اللہ کے سوا — کسی اور نے — گھڑا — بلکہ — اس — کی تصدیق — اس — چیز — کی جو اس کے — آگے ہے — اور — کتاب — کی تفصیل — ہے — اس میں — کوئی شک نہیں — رب العالمین کی طرف سے — یعنی قرآن — اللہ کی کتاب ہے — کسی نے — گھڑا نہیں؛ یہ — پچھلی کتب کی تصدیق — ہے — اس میں شک نہیں۔
۳۔ عملی سبق: قرآن — بے شک — اللہ کی طرف سے ہے؛ اس — پر ایمان لاؤ۔"""
),
1402: (
"یا — وہ — کہتے ہیں — اس نے — اسے گھڑا ہے — کہدو — تو پھر — اس — جیسی — ایک سورہ — لے آؤ — اور — اللہ کے سوا — جسے — تم — بلا سکو — بلاؤ — اگر — تم سچے ہو",
"""۱۔ قرآن — جیسی — ایک سورہ بھی نہیں بنا سکو — یہ — قرآن کی حقانیت کی دلیل۔
۲۔ ’’أَمْ يَقُولُونَ افْتَرَاهُ قُلْ فَأْتُوا بِسُورَۃٍ مِّثْلِهِ وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ‘‘ — یا — وہ — کہتے ہیں — اس نے — اسے گھڑا ہے — کہدو — تو پھر — اس — جیسی — ایک سورہ — لے آؤ — اور — اللہ کے سوا — جسے — تم — بلا سکو — بلاؤ — اگر — تم سچے ہو — یعنی قرآن — جیسی ایک — سورہ بھی — نہیں بنا سکو — یہی — اس کی — صداقت کی دلیل ہے۔
۳۔ عملی سبق: قرآن — جیسا کلام — ممکن نہیں؛ اس کی — پیروی کرو۔"""
),
1403: (
"بلکہ — انہوں نے — اس — چیز — کو جھٹلا دیا — جس — کا علم — ان — کا احاطہ نہیں کرتا — اور — ابھی — ان — تک — اس کی تاویل — نہیں پہنچی — اسی طرح — ان — سے پہلے والوں نے — جھٹلایا — پس — دیکھو — ظالموں کا انجام — کیا ہوا",
"""۱۔ بے علمی — جھٹلانے کا سبب بنتی ہے۔
۲۔ ’’بَلْ كَذَّبُوا بِمَا لَمْ يُحِيطُوا بِعِلْمِهِ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُ كَذَٰلِكَ كَذَّبَ الَّذِينَ مِن قَبْلِهِمْ فَانظُرْ كَيْفَ كَانَ عَاقِبَۃُ الظَّالِمِينَ‘‘ — بلکہ — انہوں نے — اس — چیز — کو جھٹلا دیا — جس — کا علم — ان — کا احاطہ نہیں کرتا — اور — ابھی — ان — تک — اس کی تاویل — نہیں پہنچی — اسی طرح — ان — سے پہلے والوں نے — جھٹلایا — پس — دیکھو — ظالموں کا انجام — کیا ہوا — یعنی لوگ — بے علمی کی وجہ سے — جھٹلاتے ہیں؛ گزشتہ ظالموں کا انجام — عبرت — کا باعث ہے۔
۳۔ عملی سبق: علم — حاصل کرو؛ جہالت — جھٹلانے کا سبب ہے۔"""
),
1404: (
"اور — ان — میں — کچھ — ایسے ہیں — جو — اس پر ایمان لاتے ہیں — اور — ان میں — کچھ — ایسے ہیں — جو — اس پر ایمان نہیں لاتے — اور — تمہارا — رب — فساد کرنے والوں — کو — خوب — جانتا ہے",
"""۱۔ لوگوں میں — اختلاف — کچھ ایمان والے — کچھ نہیں۔
۲۔ ’’وَمِنْهُم مَّن يُؤْمِنُ بِهِ وَمِنْهُم مَّن لَّا يُؤْمِنُ بِهِ وَرَبُّكَ أَعْلَمُ بِالْمُفْسِدِينَ‘‘ — اور — ان — میں — کچھ — ایسے ہیں — جو — اس پر ایمان لاتے ہیں — اور — ان میں — کچھ — ایسے ہیں — جو — اس پر ایمان نہیں لاتے — اور — تمہارا — رب — فساد کرنے والوں — کو — خوب — جانتا ہے — یعنی لوگوں میں — کچھ — ایمان والے ہیں — اور کچھ نہیں — اور — اللہ — مفسدین کو — خوب — جانتا ہے۔
۳۔ عملی سبق: ایمان — اپنے — دل کا فیصلہ ہے؛ اللہ — سب کو جانتا ہے۔"""
),
}
